/**
 * File storage: local disk for development / single-server installs, or any
 * S3-compatible bucket (Cloudflare R2, AWS S3, MinIO) in production.
 * Keys are generated by the server; user-supplied names never reach the path.
 */
import { DeleteObjectCommand, PutObjectCommand, S3Client } from "@aws-sdk/client-s3";
import { Inject, Injectable } from "@nestjs/common";
import { mkdir, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { ENV, type Env } from "../config/env.js";

@Injectable()
export class StorageService {
  private readonly s3: S3Client | null;
  readonly localRoot: string;

  constructor(@Inject(ENV) private readonly env: Env) {
    this.localRoot = path.resolve(env.UPLOAD_DIR);
    this.s3 =
      env.STORAGE_DRIVER === "s3"
        ? new S3Client({
            region: env.S3_REGION,
            ...(env.S3_ENDPOINT ? { endpoint: env.S3_ENDPOINT } : {}),
            credentials: { accessKeyId: env.S3_ACCESS_KEY_ID!, secretAccessKey: env.S3_SECRET_ACCESS_KEY! },
          })
        : null;
  }

  private localPath(key: string) {
    const full = path.resolve(this.localRoot, key);
    if (!full.startsWith(this.localRoot + path.sep)) throw new Error("Invalid storage key");
    return full;
  }

  async put(key: string, body: Buffer, contentType: string, disposition?: string) {
    if (this.s3) {
      await this.s3.send(
        new PutObjectCommand({
          Bucket: this.env.S3_BUCKET!,
          Key: key,
          Body: body,
          ContentType: contentType,
          CacheControl: "public, max-age=31536000, immutable",
          ...(disposition ? { ContentDisposition: disposition } : {}),
        }),
      );
      return;
    }
    const file = this.localPath(key);
    await mkdir(path.dirname(file), { recursive: true });
    await writeFile(file, body, { mode: 0o640 });
  }

  async remove(key: string) {
    if (this.s3) await this.s3.send(new DeleteObjectCommand({ Bucket: this.env.S3_BUCKET!, Key: key }));
    else await rm(this.localPath(key), { force: true });
  }

  /** A file still served from the old site's /uploads folder (or its copy, see LEGACY_ASSET_BASE). */
  legacyUrl(path: string) {
    return `${this.env.LEGACY_ASSET_BASE.replace(/\/$/, "")}/${path.replace(/^\//, "")}`;
  }

  /** Uploaded file first, then the old site's copy. */
  urlOf(key?: string | null, legacyPath?: string | null) {
    return key ? this.publicUrl(key) : legacyPath ? this.legacyUrl(legacyPath) : null;
  }

  publicUrl(key: string) {
    const base = this.env.MEDIA_PUBLIC_URL?.replace(/\/$/, "") ?? "/api/media";
    return `${base}/${key}`;
  }
}
